  $('table').style.setProperty('--sup-table-width',cols.length*125+'px');$('table').innerHTML='<table class="com-table sup-table"><thead><tr>'+cols.map(([,n])=>'<th scope="col">'+esc(n)+'</th>').join('')+'</tr></thead><tbody>'+(d.dados.length?d.dados.map(r=>'<tr>'+cols.map(([k,,type])=>'<td>'+esc(type==='date'?date(r[k]):type?fmt(r[k],type):r[k]||'—')+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="'+cols.length+'">Nenhum resultado para os filtros selecionados.</td></tr>')+'</tbody></table>';PcpMobileScroll.table($('table'));
